import sys

def read_one():
	return sys.stdin.readline().strip()

def read_spaced():
	return sys.stdin.readline().strip().split()

def read_spaced_int():
	return map(int, read_spaced())
mod = 2 * 10 ** 6 + 3
N_max = mod - 1
fac = [1] * (N_max + 1)
invfac = [1] * (N_max + 1)
inv2 = pow(2, mod - 2, mod)
for i in range(2, N_max + 1):
	fac[i] = fac[i - 1] * i % mod
invfac[N_max] = pow(fac[N_max], mod - 2, mod)
for i in reversed(range(2, N_max)):
	invfac[i] = invfac[i + 1] * (i + 1) % mod

def binomial(n, k):
	if n < k or k < 0:
		return 0
	return fac[n] * invfac[k] * invfac[n - k] % mod

def get_digits(N, B):
	D = []
	while N:
		(N, d) = divmod(N, B)
		D.append(d)
	return D

def catalan(N):
	(D1, D2) = (get_digits(N, mod), get_digits(2 * N, mod))
	ans = 1
	for i in range(len(D1)):
		if D1[i] > D2[i]:
			return 0
		ans = ans * binomial(D2[i], D1[i]) % mod
	return ans

def S1(N):
	return (N + 2) * pow(2, N - 1, mod) % mod

def S2(N):
	return ((N + 2) * pow(2, 2 * N - 1, mod) - inv2 * N * catalan(N)) % mod

def S3(N):
	if N == 1:
		return 9
	c = catalan(N)
	return ((N + 2) * pow(2, 3 * N - 1, mod) - 3 * N * c * pow(2, N - 2, mod)) % mod

def solve(N, M):
	ans = (M - N) * pow(pow(2, N, mod) - 1, 3, mod) % mod
	ans = (ans + S3(N) - 3 * S2(N) + 3 * S1(N) - N - 1) % mod
	return ans
T = int(read_one())
for _ in range(T):
	(N, M) = read_spaced_int()
	print(solve(N - 1, M))
